initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a Context Source Registration Subscription (CSRS1)
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Context Source Registration Subscription with Response Status Code set to 204     and
        Retrieve Context Source Registration Subscription with Response Status Code set to ${response1.status_code}
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'DELETE'
        Delete Context Source Registration Subscription with id set to '${subscription_id}'
}
